CREATE TABLE IF NOT EXISTS public.light_forge_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, recipe_id uuid NOT NULL REFERENCES public.light_forge_recipes(id), input_nft_ids uuid[] NOT NULL, output_nft_id uuid, echo_granted boolean NOT NULL DEFAULT false, camly_burned integer NOT NULL, xp_awarded integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS light_forge_log_user_idx ON public.light_forge_log(user_id, created_at DESC); ALTER TABLE public.light_forge_log ENABLE ROW LEVEL SECURITY; CREATE POLICY "forge_log_owner_read" ON public.light_forge_log FOR SELECT USING (auth.uid() = user_id);